CREATE TABLE `lib_collections` ( `CollectionId` INT NOT NULL AUTO_INCREMENT , `LibraryId` INT NOT NULL , `CollectionName` VARCHAR(128) NOT NULL , `Description` VARCHAR(255) NULL DEFAULT NULL , `ReferenceRegex` VARCHAR(255) NULL DEFAULT NULL , `IsActive` BIT NOT NULL DEFAULT b'1' , `PublicNotes` VARCHAR(1000) NULL DEFAULT NULL , `PublicNotesUpdatedOn` DATETIME NULL DEFAULT NULL , `PublicNotesUpdatedBy` INT NULL DEFAULT NULL , `AdminNotes` VARCHAR(1000) NULL DEFAULT NULL , `AdminNotesUpdatedOn` DATETIME NULL DEFAULT NULL , `AdminNotesUpdatedBy` INT NULL DEFAULT NULL , `UpdatedOn` DATETIME NULL DEFAULT NULL , `UpdatedBy` INT NULL DEFAULT NULL , PRIMARY KEY (`CollectionId`)) ENGINE = InnoDB CHARSET=utf8 COLLATE utf8_general_ci;
ALTER TABLE `lib_collections` ADD UNIQUE( `LibraryId`, `CollectionName`);
ALTER TABLE `lib_books` ADD `collection_id` INT NULL DEFAULT NULL AFTER `library_id`;
